node <<'NODE'
'use strict';
var assert = require('assert');
var Denque = require('./');
for (var capacity = 1; capacity <= 8; capacity++) {
  for (var n = 0; n <= 12; n++) {
    var values = [];
    for (var i = 0; i < n; i++) values.push(i % 4 === 0 ? 0 : i % 4 === 1 ? false : i % 4 === 2 ? '' : { id: i });
    var q = new Denque([], { capacity: capacity });
    values.forEach(function (value) { q.push(value); });
    if (n > 2) { q.shift(); q.push(values[0]); }
    var before = q.toArray();
    var beforeCapacity = q._list.length;
    var expected = before.filter(function (_, index) { return index % 3 === 1; });
    var removed = q.removeWhere(function (_, index) { return index % 3 !== 1; });
    assert.strictEqual(removed, before.length - expected.length);
    assert.strictEqual(q._list.length, beforeCapacity);
    assert.deepStrictEqual(q.toArray(), expected);
    q.push('after');
    q.unshift('before');
    assert.ok(q.length <= capacity);
  }
}
console.log('capacity checks passed');
